+addRegime.star <- function(object, gmatrix, rob=FALSE, sig=0.05, trace = TRUE, ...)
+{
+
+  e <-  object$residuals;
+  s_t <- object$model.specific$thVar;
+  nG <- NCOL(gmatrix);
+  normG <- norm(Matrix(G * e))
+
+  # Compute the rank of G' * G
+  G2 <- t(G) %*% G;
+  s <- svd(G2);
+  tol <- max(dim(G2)) * s[1]$d * 2.2204e-16
