+      indmin <- min(which(lambda> 0.99999));
+      GPCA <- t(PC%*%t(G));
+      GPCA <- GPCA[, 1:indmin];
+      b <- solve(t(GPCA) %*% GPCA) %*% t(GPCA) %*% e;
+      u <-  e - GPCA %*% b;
+      xH0 <- GPCA;
+    } else {
+      b <- solve(t(G) %*% G) %*% t(G) %*% e;
+      u <- e - G %*% b;
+      xH0 <- G;
+    }
+  } else {
+    u <- e;
+    if(rG < nG) {
+      PCtmp <- princomp(G);
+      PC <- PCtmp$loadings;
+#      GPCA <- PCtmp$scores;
+      lambda <- cumsum(PCtmp$sdev^2 / sum(PCtmp$sdev^2));
+      indmin <- min(which(lambda> 0.99999));
+      GPCA <- t(PC%*%t(G));
+      GPCA <- GPCA[, 1:indmin];
+      xH0 <- GPCA;
+    } else {
+      xH0 = G;
+    }
+  }

-    m <- m + 1;
